#!/usr/bin/env python3
"""Compute deterministic numeric ground truth for CSX-242_Q2."""

from __future__ import annotations

import json
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any


TASK_ID = "CSX-242_Q2"
EVENT_ID = "CSX-242"
TARGET_FAMILY = "earthquake_aftershock_alert_timing"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_catalogs/event_catalogs_009_05_event_specific_usgs_comcat_USGS_ComCat_earthquake_search_for_package_dates.json.json",
    "data/event_catalogs/event_catalogs_008_04_event_specific_disaster_catalog_GDACS_event_list_for_package_time_window.json.json",
]


def load_json(rel_path: str) -> dict[str, Any]:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def dt_from_ms(ms: int) -> datetime:
    return datetime.fromtimestamp(ms / 1000, tz=timezone.utc)


def iso_from_ms(ms: int) -> str:
    return dt_from_ms(ms).isoformat().replace("+00:00", "Z")


def dt_from_alert(text: str) -> datetime:
    clean = text.strip()
    if clean.endswith("Z"):
        clean = clean[:-1] + "+00:00"
    dt = datetime.fromisoformat(clean)
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def iso_from_alert(text: str) -> str:
    return dt_from_alert(text).isoformat().replace("+00:00", "Z")


def build_rubric() -> dict[str, Any]:
    criteria = [
        {
            "name": "mainshock_timestamp",
            "points": 4,
            "description": "Uses the Gorkha mainshock record with id us20002926 and timestamp 2015-04-25T06:11:25.950000Z.",
        },
        {
            "name": "later_alert_filter",
            "points": 4,
            "description": "Filters Nepal EQ disaster-alert records to those more than one minute after the mainshock, yielding six later alerts.",
        },
        {
            "name": "largest_alert_rule",
            "points": 4,
            "description": "Uses the later Nepal alert with the largest severity value, M7.3 at 2015-05-12T07:05:19Z.",
        },
        {
            "name": "elapsed_day_formula",
            "points": 4,
            "description": "Computes (later alert timestamp minus mainshock timestamp) divided by 86,400 seconds, giving 17.037420 days before rounding.",
        },
        {
            "name": "requested_json_and_rounding",
            "points": 4,
            "description": "Returns elapsed_days_to_largest_later_alert_rounded as 17.0 days in the requested JSON field with a short timing interpretation.",
        },
    ]
    return {"total_points": sum(item["points"] for item in criteria), "criteria": criteria}


def main() -> None:
    event_meta = load_json(SOURCE_FILES[0])
    sequence_catalog = load_json(SOURCE_FILES[1])
    alert_catalog = load_json(SOURCE_FILES[2])

    mainshock = next(feature for feature in sequence_catalog["features"] if feature["id"] == "us20002926")
    main_props = mainshock["properties"]
    main_time = main_props["time"]
    main_dt = dt_from_ms(main_time)
    main_alert_cutoff = main_dt + timedelta(minutes=1)

    later_alerts = []
    for feature in alert_catalog["features"]:
        props = feature["properties"]
        if props.get("eventtype") != "EQ" or props.get("country") != "Nepal":
            continue
        severity = props.get("severitydata", {}).get("severity")
        if severity is None:
            continue
        alert_dt = dt_from_alert(props["fromdate"])
        if alert_dt > main_alert_cutoff:
            later_alerts.append(feature)

    largest_alert = max(
        later_alerts,
        key=lambda feature: (
            feature["properties"]["severitydata"]["severity"],
            dt_from_alert(feature["properties"]["fromdate"]).timestamp(),
            str(feature.get("id", "")),
        ),
    )
    largest_props = largest_alert["properties"]
    largest_alert_dt = dt_from_alert(largest_props["fromdate"])
    elapsed_seconds = (largest_alert_dt - main_dt).total_seconds()
    elapsed_days_exact = elapsed_seconds / 86_400
    elapsed_days_rounded = round(elapsed_days_exact, 1)

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic_numeric",
        "primary_gt": {
            "answer": elapsed_days_rounded,
            "answer_field": "elapsed_days_to_largest_later_alert_rounded",
            "target_family": TARGET_FAMILY,
            "units": "days",
            "tolerance": 0.05,
            "formula": "round((largest_later_alert_time_utc - mainshock_time_utc).total_seconds()/86400, 1)",
            "interpretation": "Largest later Nepal EQ alert occurred about 17.0 days after the Gorkha mainshock.",
        },
        "key_values": {
            "event_name": event_meta["event_name"],
            "mainshock_id": mainshock["id"],
            "mainshock_magnitude": main_props["mag"],
            "mainshock_time_utc": iso_from_ms(main_time),
            "later_nepal_alert_count": len(later_alerts),
            "largest_later_alert_magnitude": largest_props["severitydata"]["severity"],
            "largest_later_alert_time_utc": iso_from_alert(largest_props["fromdate"]),
            "elapsed_seconds": round(elapsed_seconds, 2),
            "elapsed_days_exact": round(elapsed_days_exact, 6),
            "elapsed_days_to_largest_later_alert_rounded": elapsed_days_rounded,
        },
        "deterministic_evaluation": {
            "field": "answer.elapsed_days_to_largest_later_alert_rounded",
            "expected": elapsed_days_rounded,
            "tolerance": 0.05,
            "rounding": "one_decimal_day",
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }

    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(output, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
